mapper.select:
SELECT cl.id, cl.title, cl.summary, cl.create_time, CASE WHEN cl.is_anonymous = 0 THEN u.userName ELSE '匿名' END AS userName FROM confession_log cl LEFT JOIN user u ON cl.user_id = u.id
AND cl.title LIKE CONCAT('%', #{title}, '%')
AND cl.type = #{type}
AND cl.create_time >= #{createTimeStart}
AND cl.create_time <= #{createTimeEnd}
order by create_time
